"""Write Sources/SongWorkbench/ChordNetVocabulary.swift from export_coreml.py's ChordNetVocabulary.json:
the decoder's chords with their (triad, bass, 7, 9, 11, 13) head indices, as a Swift table so the app
and the tests share it without a bundled resource."""
import json
import sys

source, destination = sys.argv[1:3]
data = json.load(open(source))
lines = [
    "// Generated by tools/chord_model_export/generate_vocabulary.py from the music-x-lab",
    "// ISMIR2019-Large-Vocabulary-Chord-Recognition decoder (MIT). Do not edit by hand.",
    "",
    "extension ChordNetDecoder {",
    "    /// Log-probability charged for changing chord between frames (the decoder's diff_trans_penalty).",
    f"    static let changePenalty: Float = {data['changePenalty']}",
    "",
    "    /// Every chord the decoder can name: Harte label and its (triad, bass, seventh, ninth,",
    "    /// eleventh, thirteenth) head indices; -1 = that head does not apply.",
    "    static let vocabulary: [(name: String, heads: [Int])] = [",
]
for chord in data["chords"]:
    heads = ", ".join(str(x) for x in chord["array"])
    lines.append(f'        ("{chord["name"]}", [{heads}]),')
lines += ["    ]", "}", ""]
open(destination, "w").write("\n".join(lines))
print(len(data["chords"]), "chords")
